importScripts('https://storage.googleapis.com/workbox-cdn/releases/6.5.4/workbox-sw.js');

// Precache files generated by workbox-build (self.__WB_MANIFEST will be replaced at build time)
workbox.precaching.precacheAndRoute([
  {url: '/offline.html', revision: '1'}
]);

// Network first for navigation (HTML pages)
workbox.routing.registerRoute(
  ({request}) => request.mode === 'navigate',
  new workbox.strategies.NetworkFirst({
    cacheName: 'pages',
    plugins: [
      new workbox.expiration.ExpirationPlugin({maxEntries: 50})
    ]
  })
);

// Fallback to offline page when navigation fails
defineFallback = async ({event}) => {
  if (event.request.mode === 'navigate') {
    return caches.match('/offline.html');
  }
  return Response.error();
};
workbox.routing.setCatchHandler(defineFallback);
